sp_header_footer.client_script:
api.controller =  function ($rootScope, $scope, snRecordWatcher, spUtil, $location, $uibModal, cabrillo, $timeout, $window, i18n, spAriaUtil, $element) {

	$scope.logoText = i18n.format(i18n.getMessage('Go to {0} Homepage'), $scope.portal.title);
	$scope.collapse = function() {
		$rootScope.$emit('sp-navbar-collapse');
	}

	$scope.avatarProfile = {
		userID: $scope.user.sys_id,
		name: $scope.user.name,
		initials: $window.NOW.user_initials
	};

	if ($window.NOW.user_avatar) {
		$scope.avatarProfile.userImage = $window.NOW.user_avatar;
	}

	if (cabrillo.isNative()) {
		if ($window.innerWidth < 767) {
			$scope.isViewNative = true;
		} else {
			$scope.isViewNativeTablet = true;
		}
	}


	$scope.openPopUp = function() {
		var url = "$chat_support.do?queueID=" + $scope.data.connect_support_queue_id;
		var popup = window.open (url, "popup", "width=900, height=600");
	};

	$scope.openLogin = function () {
		$scope.modalInstance = $uibModal.open({
			templateUrl: 'modalLogin',
			scope: $scope
		});

		var pageRoot = angular.element('.sp-page-root');
		$scope.modalInstance.rendered.then(function() {
			var $uibModalStack = $injector.get('$uibModalStack');
			var modalObj = $uibModalStack.getTop();
			var modal = modalObj.value.modalDomEl;

			modal.attr('aria-label', modal.find('.panel-title').html());
			modal.attr('aria-modal', 'true');
			pageRoot.attr('aria-hidden', 'true');
		});

		$scope.modalInstance.closed.then(function() {
			pageRoot.attr('aria-hidden', 'false');
		});
	};

	var mdScreenSize = isMDScreenSize();
	$scope.showSMAvatar = isMDScreenSize();
	$scope.showAvatar = !isMDScreenSize();

	$scope.isAgentChatConfigured = g_has_agent_chat_config;

	var nav = document.getElementById('responsiveNav');

	function isMDScreenSize() {
		if (nav)
			return nav.classList.contains('responsive-tablet');
		else return false;
	}

	function updateResponsiveClasses(width) {
		if (width <= 992) {
			nav.classList.add('responsive-tablet');
			nav.classList.remove('responsive-desktop');
		} else {
			nav.classList.add('responsive-desktop');
			nav.classList.remove('responsive-tablet');
		}
		if(mdScreenSize !== isMDScreenSize() && (!$scope.showSMAvatar || !$scope.showAvatar)){
			$scope.showSMAvatar = true;
			$scope.showAvatar = true;
		}
	}

	var observer = new ResizeObserver(function(entries) {
		if (entries && entries[0]) {
			updateResponsiveClasses(entries[0].contentRect.width);
		}
	});
	observer.observe(nav);

	$rootScope.$on('sp.avatar_changed', function(evt, obj) {
		$scope.userID = "";
		$scope.newAvatarId = obj.newAvatarId;
		$timeout(function(){
			$scope.userID = $scope.user.sys_id;
			$("#profile-dropdown .sub-avatar").css({"background-image": 'url("' + $scope.newAvatarId + '.iix?t=small")', "color": "transparent"});
		});
	});

	$scope.isHomepage = function() {
		if (!$scope.page.id)
			return true;

		if ($scope.page.id == $scope.portal.homepage_dv)
			return true;

		return false;
	};

	// Initialize keyboard navigation for header dropdowns after DOM is ready
	$timeout(function() {
		function isMDScreenSize() {
			return window.matchMedia('(max-width: 992px)').matches;
		}

		var navbarElement = $element.find('.navbar');
		if (navbarElement.length > 0) {
			spAriaUtil.initDropdownKeyboardNav(navbarElement, {
				checkMdScreenSize: true,
				isMDScreenSize: isMDScreenSize
			});
		}
	});

};

sp_header_footer.css:
/* --- NEW THEME OVERRIDES --- */
@import url('https://fonts.googleapis.com/css2?family=Michroma&display=swap');

.navbar {
  transition: 250ms opacity ease-in-out;
  -webkit-transition: 250ms opacity ease-in-out;
  border: 0;
  /* Removed the standard border-bottom */
  background-color: transparent !important; /* Force transparent background */
}

/* Force header text, brand, and mobile hamburger icons to be white */
/* Force the portal title to be a single line and use Michroma */
.navbar-inverse .navbar-brand {
  position: relative; 
  z-index: 1; /* Ensures the text and container stay on top */
}
/* Style and position the background SVG sparkle */
.ai-sparkle-bg {
  position: absolute;
  top: 50%;
  left: 105%; /* Adjust this to move it left/right relative to the text */
  transform: translate(-50%, -50%); /* Centers the SVG */
  width: 55px; /* Size of the sparkles */
  height: 55px;
  z-index: -1; /* Pushes it behind the text */
  opacity: 0.6; /* Adjust this to make the gradient brighter or softer */
  pointer-events: none; /* Ensures the link is still clickable */
}
.navbar-inverse .navbar-brand span {
  font-family: 'Michroma', sans-serif !important;
  color: #ffffff !important;
  white-space: nowrap !important; /* Prevents the text from wrapping */
  width: auto !important; /* Overrides the default calc(100% - 3rem) constraint */
  font-size: 18px; /* Adjust this value if the font is too large/small */
}
.navbar-inverse .navbar-brand span,
.navbar-inverse .navbar-nav > li > a,
.navbar-inverse .navbar-text {
  color: #ffffff !important;
}

/* Make the hamburger menu lines white */
.navbar-inverse .navbar-toggle .icon-bar {
  background-color: #ffffff !important; 
}

/* Soft hover effect for links */
.navbar-inverse .navbar-nav > li > a:hover {
  color: #e0e0e0 !important;
}

/* Style the profile dropdown to match the dark space theme */
.dropdown-menu {
  background-color: #24243e; /* Dark purple from your background */
  border: 1px solid rgba(255, 255, 255, 0.1);
}
.dropdown-menu > li > a {
  color: #ffffff !important;
}
.dropdown-menu > li > a:hover,
.dropdown-menu > li > a:focus {
  background-color: #302b63; /* Lighter purple on hover */
  color: #ffffff !important;
}

/* --- ORIGINAL WIDGET CSS --- */

.navbar-fade {
  opacity: 0.4;
}

.navbar-inverse .navbar-toggle {
  border-color: transparent; /* Changed to transparent to remove the box around hamburger */
}

header[role="banner"],
.nav > li > a {
  max-height: 60px;
}

.nav > li > a span.fa{
  margin-left: 0.2rem;
}

.responsive-tablet {
  .nav > li > a {
    padding-right: 0.5rem;
    padding-left: 0.5rem;
  }
}

.navbar-brand {
  max-height: 60px;
  padding: 0;
  padding-bottom: 0.5rem;
}

.navbar-brand img, .navbar-brand span {
  margin-left: $sp-logo-margin-x;
  margin-right: $sp-logo-margin-x;
  margin-top: $sp-logo-margin-y;
  margin-bottom: $sp-logo-margin-y;
  display: block;
  max-height: $sp-logo-max-height;
  max-width: $sp-logo-max-width;
  position: relative;
  top: 50%;
  -webkit-transform: translateY(-50%);
  -ms-transform: translateY(-50%);
  transform: translateY(-50%);
  overflow: hidden;
  width: calc(100% - 3rem);
}

.responsive-tablet {
  .navbar-brand img, .navbar-brand span {
    max-width: $sp-logo-mobile-max-width;
  }
}

.breadcrumb-container {
  background-color: transparent; /* Made transparent */
}

/* for mobile app */
.navbar-inverse.is-native {
  background-color: #405060;
}

nav {
  margin-bottom: 0px;
  border-radius: 0px;

 .toggle-dropdown {
    height: 60px;
  }

}

.navbar-right {
  padding-right: 0px;
  padding-left: 7px;
}

.navbar-nav {
margin: 0px;
}

.scrollable-dropdown {
  max-height: 80vh;
  overflow: auto;
  height: auto;
}

.is-native {
 .scrollable-dropdown {
  max-height: 100vh;
  overflow: scroll;
  height: auto;
	}
}

.responsive-desktop {
  .navbar-right {
    display: flex !important;
    height: auto !important;
  }
}

.responsive-tablet {
  .navbar-toggle {
    display: block;
  }
  .navbar-header {
    float: none;
  }
  .navbar-left,.navbar-right {
    float: none !important;
  }
  .navbar-nav {
    float: none !important;
  }
  .navbar-nav > li {
    float: none;
  }
  .navbar-nav > li > a {
    padding-top: 1rem ;
    padding-bottom: 1rem;
  }
}

@media screen and (-ms-high-contrast: active), (forced-colors: active) {
  .navbar-brand,
  .navbar-nav >li >a,
  .skip-link,
  .btn.btn-primary,
  .btn.btn-danger,
  .navbar-inverse .navbar-toggle {
    &:focus {
      outline-offset: -4px !important;
    }
  }
}

sp_header_footer.link:
function link(scope, element) {
	var KEY = {
		TAB: 9,
		ESC: 27
	};

	function isMDScreenSize() {
		return window.matchMedia('(max-width: 992px)').matches;
	}

	var navbarContainer = $('#sp-nav-bar');
	navbarContainer.on('shown.bs.collapse', function () {
		$('a:visible', navbarContainer).first().focus();
	});

	// Additional mobile-specific ESC key handling for Stock Header
	$(element).on('keyup', function(event) {
		if (event.which == KEY.ESC) {
			var mdScreenSize = isMDScreenSize();
			if (mdScreenSize && $('.navbar-right').attr("aria-expanded")) {
				closeMobileMenu();

				if ($(event.target).parents(".navbar-right").length > 0)
					$('.navbar-toggle').focus();
			}
		}
	});

	$(element).on('click.nav','.navbar-collapse.in',function(e) {
		var target = $(e.target);
		if (target.is('a')) {
			if (target.hasClass('sp-menu-has-items'))
				return; // menu item has a submenu, so just toggle it

			// collapse mobile nav if clicked an anchor
			$(this).removeClass('in').addClass('collapse');
			return;
		}

		if (target.parent().hasClass("toggle-dropdown")) {
			// collapse mobile nav if parent has toggle-dropdown class
			$(this).removeClass('in').addClass('collapse');
			return;
		}

		// if neither target nor parent is an anchor, do nothing
		if (!target.parent().is('a'))
			return;

		// collapse mobile nav if target is part of a submenu
		if (target.parents("ul.dropdown-menu").length > 0)
			$(this).removeClass('in').addClass('collapse');
	});

	// clicking outside the mobile menu should close the mobile menu
	$(document).on('click', function(e) {
		var target = $(e.target);
		if (target.parents('.navbar-right').length == 0) {
			closeMobileMenu();
		}
	});

	// Close the mobile menu when focus goes out of the menu
	$('.navbar-right').on('keydown', 'a', function(event) {
		if (($(this).is($('.navbar-right a').last()) && event.which == KEY.TAB && !event.shiftKey) || ($(this).is($('.navbar-right a').first()) && event.which == KEY.TAB && event.shiftKey)) {
			closeMobileMenu();
			setTimeout(function () {
				window.scrollBy(0,-200);
			});
		}
	});

	function closeMobileMenu() {
		$('.navbar-right').collapse('hide');
	}
}

sp_header_footer.script:
// Defines the support queue ID that will be linked to by the Live Chat link in header
data.connect_support_queue_id = $sp.getValue('sp_chat_queue');
data.login_page = $sp.getValue('login_page');
data.profileBtnMsg = gs.getMessage("User options");
data.toggleMsg = gs.getMessage("Toggle navigation");
var menu = $sp.getValue("sp_rectangle_menu");
data.menu = $sp.getWidgetFromInstance(menu);
//data.langSelector = pm.isActive('com.glide.i18n')? $sp.getWidget('sp-lang-selector') : "";
if (data.menu && data.menu.data) {
	data.menu.data.replace = true;
	// Hide login if menu already has link to login
	data.hasLogin = false;
	if (data.menu.data.menu.items) {
		data.hasMenuItems = data.menu.data.menu.items.length > 0;
		for(var i in data.menu.data.menu.items) {
			var item = data.menu.data.menu.items[i];
			if (item.type == 'page' && item.sp_page == data.login_page)
				data.hasLogin = true;
		}
	}
}

data.loginWidget = $sp.getWidgetFromInstance('login-modal');
data.lightfallBgWidget = $sp.getWidget('lightfall-background');
